{"cards": [{"node_code": "N_fa279dd890d30c5a", "definition": "研究肩、肘、前臂、腕、手及足部以外上肢结构的急性创伤性损伤，涵盖骨折、脱位、肌腱神经血管损伤及开放伤的诊断与治疗。", "boundary": "本节点聚焦于上肢解剖区域的急性外伤。包括肱骨、尺桡骨、腕骨及掌指骨骨折，肩肘腕关节脱位，以及伴随的软组织损伤。与下肢创伤的区别在于解剖部位不同；与脊柱骨盆创伤的区别在于不涉及躯干中轴骨骼。", "includes": ["肩肘腕及前臂急性骨折与脱位", "手部创伤及肌腱神经血管损伤", "上肢开放伤与复合伤处理"], "excludes": ["下肢及躯干中轴骨骼创伤（归入相应节点）", "慢性上肢退行性病变（归入关节外科）"], "sibling_distinctions": [{"other_code": "N_0157fd2e422fb4c3", "rule": "上肢创伤处理肩至手指的损伤；下肢创伤处理髋至足部的损伤。"}, {"other_code": "N_72769a71e18fec29", "rule": "上肢创伤处理四肢远端及近端上肢；脊柱与骨盆创伤处理躯干中轴及骨盆环损伤。"}], "cross_boundary_rule": "上肢各部位急性骨折、脱位及软组织损伤归入上肢创伤；若合并脊柱或骨盆损伤，需分别挂载至脊柱与骨盆创伤。"}, {"node_code": "N_0157fd2e422fb4c3", "definition": "研究髋、膝、小腿、踝、足及下肢结构的急性创伤性损伤，涵盖股骨、胫腓骨、足部骨折及关节脱位的诊断与治疗。", "boundary": "本节点聚焦于下肢解剖区域的急性外伤。包括股骨颈、转子间、胫腓骨及足部骨折，髋膝踝关节脱位，以及伴随的血管神经损伤。与上肢创伤的区别在于解剖部位不同；与脊柱骨盆创伤的区别在于不涉及躯干中轴骨骼。", "includes": ["髋膝踝及小腿急性骨折与脱位", "足部创伤及跟腱神经血管损伤", "下肢开放伤与复合伤处理"], "excludes": ["上肢及躯干中轴骨骼创伤（归入相应节点）", "慢性下肢退行性病变（归入关节外科）"], "sibling_distinctions": [{"other_code": "N_fa279dd890d30c5a", "rule": "下肢创伤处理髋至足部的损伤；上肢创伤处理肩至手指的损伤。"}, {"other_code": "N_72769a71e18fec29", "rule": "下肢创伤处理四肢远端及近端下肢；脊柱与骨盆创伤处理躯干中轴及骨盆环损伤。"}], "cross_boundary_rule": "下肢各部位急性骨折、脱位及软组织损伤归入下肢创伤；若合并脊柱或骨盆损伤，需分别挂载至脊柱与骨盆创伤。"}, {"node_code": "N_72769a71e18fec29", "definition": "研究脊柱、骨盆及骶髂关节的急性创伤性损伤，涵盖脊柱骨折、脱位、骨盆环骨折及伴随的神经血管损伤的诊断与治疗。", "boundary": "本节点聚焦于躯干中轴骨骼及骨盆环的急性外伤。包括颈椎、胸椎、腰椎骨折，脊柱脱位，骨盆骨折及骶髂关节损伤。与四肢创伤的区别在于解剖部位为躯干中轴；与脊柱外科的区别在于侧重急性创伤而非退变或畸形。", "includes": ["颈椎胸椎腰椎急性骨折与脱位", "骨盆环骨折及骶髂关节损伤", "脊柱创伤伴神经血管损伤处理"], "excludes": ["四肢远端及近端创伤（归入上肢或下肢创伤）", "非创伤性脊柱退变或畸形（归入脊柱外科）"], "sibling_distinctions": [{"other_code": "N_fa279dd890d30c5a", "rule": "脊柱与骨盆创伤处理躯干中轴及骨盆环；上肢创伤处理肩至手指的损伤。"}, {"other_code": "N_0157fd2e422fb4c3", "rule": "脊柱与骨盆创伤处理躯干中轴及骨盆环；下肢创伤处理髋至足部的损伤。"}], "cross_boundary_rule": "脊柱、骨盆及骶髂关节急性骨折、脱位归入脊柱与骨盆创伤；若合并四肢损伤，需分别挂载至上肢或下肢创伤。"}]}
